// PATCH /api/posts/:id/view - atomic view counter increment
router.patch('/posts/:id/view', async (req, res, next) => {
  try {
    const updated = await prisma.post.update({
      where: { id: Number(req.params.id) },
      data: { views: { increment: 1 } }
    });
    res.json(updated);
  } catch (err) { next(err); }
});

